insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, auto_check)
select x.id, v.ci, v.ex, v.dn::jsonb, v.ac::jsonb
from (values
(1, 1, 'الكيمياء العضوية هي فرع الكيمياء الذي يدرس المركبات التي تحتوي على الكربون.', '["الكيمياء التحليلية تُعنى بتحديد مكونات المادة وأنواعها وكمياتها.","","الكيمياء الذرية تُعنى بتركيب الذرة: النظائر والتركيب الإلكتروني والروابط ونظريات تركيب المادة.","الكيمياء الفيزيائية تدرس سلوك المواد وتفاعلاتها وخصائصها والطاقة المصاحبة لها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-28T19:44:48.400Z"}'::jsonb),
(2, 1, 'تحلل مواد التغليف في البيئة من موضوعات الكيمياء البيئية التي تدرس أثر المواد في البيئة.', '["الكيمياء الحيوية تدرس المواد والعمليات والتفاعلات داخل المخلوقات الحية.","","صحيح أن كثيرًا من مواد التغليف عضوية، لكن دراسة تحللها في البيئة من اختصاص الكيمياء البيئية.","الكيمياء الفيزيائية تدرس سلوك المواد وتفاعلاتها وخصائصها والطاقة المصاحبة لها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-28T19:44:48.400Z"}'::jsonb),
(3, 0, 'النظائر والروابط والتركيب الإلكتروني من موضوعات تركيب الذرة، وهي مجال الكيمياء الذرية.', '["","الكيمياء الحيوية تدرس المواد والعمليات والتفاعلات داخل المخلوقات الحية.","الكيمياء العضوية تدرس المركبات التي تحتوي على الكربون.","الكيمياء التحليلية تُعنى بتحديد مكونات المادة وأنواعها وكمياتها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-28T19:44:48.400Z"}'::jsonb),
(4, 0, 'الكيمياء الحيوية تدرس المواد والعمليات في المخلوقات الحية.', '["","الكيمياء الفيزيائية تدرس سلوك المواد وتفاعلاتها وخصائصها والطاقة المصاحبة لها.","الكيمياء التحليلية تُعنى بتحديد مكونات المادة وأنواعها وكمياتها.","الكيمياء الذرية تُعنى بتركيب الذرة: النظائر والتركيب الإلكتروني والروابط ونظريات تركيب المادة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-28T19:44:48.400Z"}'::jsonb),
(5, 1, 'الكيمياء الفيزيائية تدرس سلوك المواد وتفاعلاتها وخصائصها والطاقة المصاحبة لها.', '["الكيمياء الذرية تُعنى بتركيب الذرة: النظائر والتركيب الإلكتروني والروابط ونظريات تركيب المادة.","","الكيمياء الحيوية تدرس المواد والعمليات والتفاعلات داخل المخلوقات الحية.","الكيمياء النووية تدرس التفاعلات النووية والنشاط الإشعاعي."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-28T19:44:48.400Z"}'::jsonb),
(6, 2, 'دراسة التلوث وأثر المواد في الهواء والماء والتربة من مجال الكيمياء البيئية.', '["قد تُستخدم التحليلية لقياس الملوثات، لكن دراسة التلوث نفسه مجال الكيمياء البيئية.","الكيمياء العضوية تدرس المركبات التي تحتوي على الكربون.","","الكيمياء الذرية تُعنى بتركيب الذرة: النظائر والتركيب الإلكتروني والروابط ونظريات تركيب المادة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-28T19:44:48.400Z"}'::jsonb),
(7, 1, 'الروابط وأشكال المدارات والتركيب الإلكتروني من موضوعات الكيمياء الذرية.', '["الكيمياء الفيزيائية تدرس سلوك المواد وتفاعلاتها وخصائصها والطاقة المصاحبة لها.","","الكيمياء الحيوية تدرس المواد والعمليات والتفاعلات داخل المخلوقات الحية.","الكيمياء العضوية تدرس المركبات التي تحتوي على الكربون."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-28T19:44:48.400Z"}'::jsonb),
(8, 3, 'الكيمياء التحليلية تحدد أنواع المواد ومكوناتها وكمياتها.', '["الكيمياء الذرية تُعنى بتركيب الذرة: النظائر والتركيب الإلكتروني والروابط ونظريات تركيب المادة.","الكيمياء الحيوية تدرس المواد والعمليات والتفاعلات داخل المخلوقات الحية.","الكيمياء العضوية تدرس المركبات التي تحتوي على الكربون.",""]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-28T19:44:48.400Z"}'::jsonb),
(9, 1, 'نظريات تركيب المادة (كالنظرية الذرية ونماذج الذرة) من مجال الكيمياء الذرية.', '["الكيمياء التحليلية تُعنى بتحديد مكونات المادة وأنواعها وكمياتها.","","الكيمياء الفيزيائية تدرس سلوك المواد وتفاعلاتها وخصائصها والطاقة المصاحبة لها.","الكيمياء النووية تدرس التفاعلات النووية والنشاط الإشعاعي."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-28T19:44:48.400Z"}'::jsonb),
(10, 0, 'التفاعلات داخل المخلوقات الحية مجال الكيمياء الحيوية.', '["","الكيمياء الذرية تُعنى بتركيب الذرة: النظائر والتركيب الإلكتروني والروابط ونظريات تركيب المادة.","كثير من مواد المخلوقات الحية عضوية، لكن دراسة تفاعلاتها داخل الجسم مجال الكيمياء الحيوية.","الكيمياء الفيزيائية تدرس سلوك المواد وتفاعلاتها وخصائصها والطاقة المصاحبة لها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-28T19:44:48.401Z"}'::jsonb),
(11, 0, 'البلاستيك بوليمرات أساسها سلاسل الكربون، فصناعته من مجال الكيمياء العضوية.', '["","الكيمياء التحليلية تُعنى بتحديد مكونات المادة وأنواعها وكمياتها.","الكيمياء اللاعضوية تدرس المواد التي لا تقوم على سلاسل الكربون كالأملاح والفلزات.","الكيمياء النووية تدرس التفاعلات النووية والنشاط الإشعاعي."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-28T19:44:48.401Z"}'::jsonb)
